module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    reg [1:0] current_state, next_state;

    // State encoding
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            S0: next_state = S1;
            S1: next_state = S2;
            S2: next_state = S0;
            default: next_state = S0;
        endcase
    end

    // Output logic
    assign state = current_state;

endmodule

module traffic_light (
    input clk, reset,
    output reg [2:0] light
);

    reg [1:0] state, next_state;

    // State encoding
    localparam S_RED = 2'b00, 
               S_GREEN = 2'b01, 
               S_YELLOW = 2'b10;

    // State transition
    always @(posedge clk or posedge reset) begin
        if (reset) 
            state <= S_RED;
        else 
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            S_RED: next_state = S_GREEN;
            S_GREEN: next_state = S_YELLOW;
            S_YELLOW: next_state = S_RED;
            default: next_state = S_RED;
        endcase
    end

    // Output logic
    always @(*) begin
        case (state)
            S_RED: light = 3'b100;   // Red
            S_GREEN: light = 3'b010; // Green
            S_YELLOW: light = 3'b001; // Yellow
            default: light = 3'b000; // Default
        endcase
    end

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output reg [1:0] state
);
    // Defining states
    parameter IDLE = 2'b00, MOVING_UP = 2'b01, MOVING_DOWN = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (up_request)
                        state <= MOVING_UP;
                    else if (down_request)
                        state <= MOVING_DOWN;
                    else
                        state <= IDLE;
                end
                MOVING_UP: begin
                    if (!up_request)
                        state <= IDLE;
                end
                MOVING_DOWN: begin
                    if (!down_request)
                        state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output reg [1:0] state
);

    // State encoding
    localparam IDLE = 2'b00, COIN_INSERTED = 2'b01, ITEM_SELECTED = 2'b10;

    // Sequential logic for state transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: 
                    if (coin_inserted) 
                        state <= COIN_INSERTED;
                COIN_INSERTED: 
                    if (item_selected) 
                        state <= ITEM_SELECTED;
                ITEM_SELECTED: 
                    state <= IDLE;
                default: 
                    state <= IDLE;
            endcase
        end
    end

endmodule

