module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [3:0] left, right, new_left, new_right, f_output;

    assign left = data_in[7:4];
    assign right = data_in[3:0];

    assign f_output = (right ^ KEY);  // Example f-function

    assign new_left = right;
    assign new_right = left ^ f_output;

    assign data_out = {new_left, new_right};

endmodule

