module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    reg [7:0] binary_count;
    reg [7:0] gray_count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            binary_count <= 8'b0;
            gray_count <= 8'b0;
        end else begin
            binary_count <= binary_count + 1;
            gray_count <= binary_count ^ (binary_count >> 1);
        end
    end

    assign count = gray_count;

endmodule

