module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);

  reg [1:0] state, next_state;

  // State encoding
  localparam S0 = 2'b00,
             S1 = 2'b01,
             S2 = 2'b10;

  // State register
  always @(posedge clk or negedge aresetn) begin
    if (!aresetn)
      state <= S0;
    else
      state <= next_state;
  end

  // Next-state logic
  always @(*) begin
    case (state)
      S0: next_state = x ? S1 : S0;
      S1: next_state = x ? S2 : S0;
      S2: next_state = x ? S2 : S0;
      default: next_state = S0;
    endcase
  end

  // Output logic
  always @(*) begin
    case (state)
      S0: z = 0;
      S1: z = 0;
      S2: z = 1;
      default: z = 0;
    endcase
  end

endmodule

