module TopModule (
  input clk,
  input in,
  input reset,
  output reg out
);

  reg [1:0] state, next_state;

  // State encoding
  localparam S0 = 2'b00;
  localparam S1 = 2'b01;
  localparam S2 = 2'b10;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset)
      state <= S0;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      S0: next_state = in ? S1 : S0;
      S1: next_state = in ? S2 : S0;
      S2: next_state = in ? S2 : S0;
      default: next_state = S0;
    endcase
  end

  // Output logic
  always @(*) begin
    case (state)
      S0: out = 0;
      S1: out = 0;
      S2: out = 1;
      default: out = 0;
    endcase
  end

endmodule

