module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout
);

    wire [7:0] carry;

    // Full adder logic for bit 0
    assign sum[0] = a[0] ^ b[0] ^ cin;
    assign carry[0] = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);

    // Full adder logic for bit 1
    assign sum[1] = a[1] ^ b[1] ^ carry[0];
    assign carry[1] = (a[1] & b[1]) | (a[1] & carry[0]) | (b[1] & carry[0]);

    // Full adder logic for bit 2
    assign sum[2] = a[2] ^ b[2] ^ carry[1];
    assign carry[2] = (a[2] & b[2]) | (a[2] & carry[1]) | (b[2] & carry[1]);

    // Full adder logic for bit 3
    assign sum[3] = a[3] ^ b[3] ^ carry[2];
    assign carry[3] = (a[3] & b[3]) | (a[3] & carry[2]) | (b[3] & carry[2]);

    // Full adder logic for bit 4
    assign sum[4] = a[4] ^ b[4] ^ carry[3];
    assign carry[4] = (a[4] & b[4]) | (a[4] & carry[3]) | (b[4] & carry[3]);

    // Full adder logic for bit 5
    assign sum[5] = a[5] ^ b[5] ^ carry[4];
    assign carry[5] = (a[5] & b[5]) | (a[5] & carry[4]) | (b[5] & carry[4]);

    // Full adder logic for bit 6
    assign sum[6] = a[6] ^ b[6] ^ carry[5];
    assign carry[6] = (a[6] & b[6]) | (a[6] & carry[5]) | (b[6] & carry[5]);

    // Full adder logic for bit 7
    assign sum[7] = a[7] ^ b[7] ^ carry[6];
    assign carry[7] = (a[7] & b[7]) | (a[7] & carry[6]) | (b[7] & carry[6]);

    // Final carry-out
    assign cout = carry[7];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    wire [4:0] binary_sum; // Intermediate binary sum (4 bits + carry)
    wire [3:0] corrected_sum;
    wire correction_required;

    // Step 1: Calculate binary sum including carry
    assign binary_sum = A + B + Cin;

    // Step 2: Determine if correction is needed (binary sum > 9)
    assign correction_required = (binary_sum > 9);

    // Step 3: Add correction factor (6) if correction is required
    assign corrected_sum = correction_required ? (binary_sum - 10) : binary_sum[3:0];

    // Step 4: Assign the sum and carry outputs
    assign Sum = corrected_sum;
    assign Cout = correction_required;

endmodule

