module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

	reg a_prev;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			a_prev <= 1'b0;
			rise <= 1'b0;
			down <= 1'b0;
		end else begin
			rise <= ~a_prev & a;
			down <= a_prev & ~a;
			a_prev <= a;
		end
	end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [31:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 32'd0;
            clk_div <= 1'b0;
        end else begin
            if (cnt == (NUM_DIV / 2) - 1) begin
                cnt <= 32'd0;
                clk_div <= ~clk_div;
            end else begin
                cnt <= cnt + 32'd1;
            end
        end
    end
endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output reg [2:0] ins,
    output reg [4:0] ad1,
    output reg [7:0] ad2
);

    reg [7:0] temp;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            temp <= 8'b0;
            ins <= 3'b0;
            ad1 <= 5'b0;
            ad2 <= 8'b0;
        end else begin
            if (fetch == 2'b01) begin
                temp <= data;
            end else if (fetch == 2'b10) begin
                {ins, ad1} <= temp;
            end else if (fetch == 2'b11) begin
                ad2 <= temp;
            end
        end
    end

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire feedback;

  assign feedback = out[3] ^ out[2]; // XOR between bit 3 and bit 2 of the LFSR

  always @(posedge clk or posedge rst) begin
    if (rst)
      out <= 4'b0001; // Initialize the LFSR with a non-zero value
    else
      out <= {out[2:0], feedback}; // Shift left and insert feedback at LSB
  end
endmodule

