module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg [3:0] data_meta;
reg [3:0] data_temp_1;
reg [3:0] data_temp_2;

always @(posedge clk_a or negedge arstn) begin
	if (!arstn)
		data_meta <= 4'b0;
	else if (data_en)
		data_meta <= data_in;
end

always @(posedge clk_b or negedge brstn) begin
	if (!brstn) begin
		data_temp_1 <= 4'b0;
		data_temp_2 <= 4'b0;
		dataout <= 4'b0;
	end else begin
		data_temp_1 <= data_meta;
		data_temp_2 <= data_temp_1;
		dataout <= data_temp_2;
	end
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [1:0] state, next_state;

// State encoding
localparam S0 = 2'b00,
           S1 = 2'b01,
           S2 = 2'b10,
           S3 = 2'b11;

// State transition logic
always @(posedge CLK or posedge RST) begin
    if (RST)
        state <= S0;
    else
        state <= next_state;
end

// Next state logic and output logic
always @(*) begin
    case(state)
        S0: begin
            if (IN)
                next_state = S1;
            else
                next_state = S0;
            MATCH = 0;
        end

        S1: begin
            if (IN)
                next_state = S1;
            else
                next_state = S2;
            MATCH = 0;
        end

        S2: begin
            if (IN)
                next_state = S3;
            else
                next_state = S0;
            MATCH = 0;
        end

        S3: begin
            if (IN)
                next_state = S1;
            else
                next_state = S0;
            MATCH = 1;
        end

        default: begin
            next_state = S0;
            MATCH = 0;
        end
    endcase
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

    reg [3:0] shift_reg;
    reg [2:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 4'b0;
            count <= 3'b0;
            dout <= 1'b0;
            valid_out <= 1'b0;
        end else begin
            if (count == 3'b0) begin
                shift_reg <= d;
                valid_out <= 1'b1;
            end else begin
                valid_out <= 1'b0;
            end

            dout <= shift_reg[0];
            shift_reg <= {1'b0, shift_reg[3:1]};

            count <= count + 1'b1;
            if (count == 3'b100) begin
                count <= 3'b0;
            end
        end
    end

endmodule

